/// The gallery's example of `ColorSwatch`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let arg_selected = args.bool("selected");

        let current = State::new(args.number("current") as _);
        view_fn(move || {
            let theme = Theme::raven_light();
            let options =
                [(Semantic::Accent, "Accent"), (Semantic::Success, "Success"), (Semantic::Danger, "Danger")];
            let swatches: Vec<AnyView> = options
                .iter()
                .enumerate()
                .map(|(i, (role, name))| {
                    let pick = current.clone();
                    Box::new({
                        let mut it = ColorSwatch::new(theme.color(*role), *name)
                            .selected(current.get() == i)
                            .on_click(move || pick.set(i));
                        it = it.selected(arg_selected);
                        it
                    }) as AnyView
                })
                .collect();
            HStack::new(swatches)
        })
    })
}

impl ComponentBook for ColorSwatch {
    fn book() -> Meta {
        Meta::new("Actions and inputs/ColorSwatch", render)
            .summary("Round color to pick from a palette.")
            .arg(ArgType::bool("selected", false))
            .arg(ArgType::number("current", 0.0, 0.0, 5.0, 1.0).description("How the example starts."))
            .story("Example", Args::new())
            .story("Selected", Args::new().with("selected", true))
    }
}
